SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (1180::BIGINT, 'El profe es súper buena gente, pero no sabe dar la materia, esa es la verdad. Eso sí, las evaluaciones y exámenes son accesibles aunque no sabe redactar. Si es autodidacta, de una, si no, no lo lleve con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '2703e6413a58f33d33d594adab06089699632d44fda206017e9aa025e6d70e0a'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Realmente no es un buen profesor pero si usted ve los videos de Señales y Sistemas el curso es realmente pasable, creo que él está consciente de que no enseña bien y las evaluaciones al menos comparadas con SyS son mucho más fácil'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '5a7ad5d9fd918d771092cf11d25108b823aeeba989d0944ef60a10bdfb30fe69'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'El peor profesor que jamás tuve. Enseñó en clase de todo excepto lo necesario para pasar el curso'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9be6ee206fe88fb3c08e5457305e73389bf7679fd967e366bd520084061e459a'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'El profe explica bien la materia y se nota que le interesa mucho, por lo cual cada clase es interesante y se puede aprovechar mucho. Aunque la mayor parte de la nota se definió al final del semestre, los trabajos fueron sencillos por el apoyo dado por el profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0362f64c464835bc4ce6fafdb38e081f8abb5bdca7c4eefa83b2bb4cc553f470'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'Al profe le interesa mucho esta materia y se nota en la forma que da las clases. El proyecto final no es difícil y si uno va a consulta le da buenas recomendaciones.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'f245836d1ff8e1ae0a7d25b4ab312f8d8d62a8987d78776a57405ba559b267f7'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'Un profe muy diferente al de modelos, al menos explica bien, menos estricto, califica suave, pero casi no da realimentación de las entregas, las notas aparecen mágicamente al final +70% del curso, es entendible que en 8vo S. se debe hacer un buen trabajo, pero es un curso importante, mejor Otarola'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '3cd1febf683fa58740162f46a34fae34cdaeb759c6240ec2b70bd00b2c6b993e'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'El peor profe que he tenido, en general. En serio, en la medida de lo posible, no matriculen con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '05284efc79d9f7b71397b56e7052901b70b9c99138ac8a12551a6c59151b0200'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Es el peor profesor de la carrera, las clases tienen cero esfuerzo por parte del mae y las evaluaciones parece que ni siquiera saca el rato para revisarlas, sólo aparecen las notas y no hay retroalimentación (uno nunca sabe qué hizo bien o mal).'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '201fa2cca3467884de157d0b2c980bf008942a6920049d4e1f8090026879e194'::TEXT, ARRAY[3068]::BIGINT[]),
    (1180::BIGINT, 'El peor profe que he tenido en toda mi vida, no le importa para nada que los estudiantes aprendan y nunca acepta cuando se equivoca (lo que pasa con frecuencia en los exámenes).'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes']::TEXT[], '2021-02-23T00:00:00+00:00'::TIMESTAMPTZ, '986e9c2d6aa6fc6c68d8d38e0b96b3866cb31632777387ce91ca24715bc212aa'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'No habían clases, sino "periodo de consulta" en los que realmente no se hacía nada. Las guías semanales son pésimas, y en los exámenes entran cosas que no se ven en clases. La cátedra es un chiste porque ambos profes difieren en cómo aplicar los exámenes, el profe se equivoca mucho y no va a aceptar'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd7c1bf1f532819b7ed0cb465c9e45aab9050c80d27f82a00af9ddd37a9e3a327'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'El examen final lo revisó increíblemente duro. Las tareas y el proyecto no los revisó por falta de tiempo. Deja muchos trabajos. Casi no dio clases. Se nota que sabe mucho pero al final no terminó enseñando casi nada.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'b540668449c0ba73e400eeaa50c6d2d0ae6283f32329a4a753bd5d55b5798f39'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'El profe deja muchos trabajos y al final no revisó nada. Hizo un único examen que vale 30% con una pregunta binaria que vale medio examen. En general el profe no estaba interesado en la clase, no revisó casi nada y dio pocas clases pero se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f5bf8eb547564461e4b1676b2543cba5952552d8116819c66bbe5006318d6ae6'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'Te odio Jaime.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '8230b9b57b2d034e044b36163512e1a3894d9fa1ed932fef40375a3c72e06611'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'El curso es interesante y Jaime sabe de lo que está hablando. Deja muchos trabajos pero califica suave'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '832d132bf3addb252879cce2c2d40e5b72fefa9c987a514903eb2528a84a4cdd'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'Pésimo es poco. No se nota ni una pizca de esfuerzo, ni interés en el aprendizaje del estudiantado. Sinceramente, se está robando el salario, por lo menos debería intentarlo. Por favor, no se hagan profes solo por una beca para maestría/doctorado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd45ba7943c2b728233e81084730f2783efbb55de43aeefcacebb5a3dc590f5bd'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Se para.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '1a64e58840453b701908c82b32712ac002a6b552313dda9a2ff33e8662a8d9d0'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'De no ser por el gran Jose Miguel Barboza y Pablo Alvarado no hubiera tenido oportunidad en este curso. Las "Clases" que Jaime deja son lectura directa del folleto de Pablo, por lo que sus videos tienen poco valor didáctico. Quisiera que se tomará la enseñanza en serio, Jaime podría ser buen profe.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Exámenes retadores']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '841ecdfdfbbe2c66244aac09c2c36aff7cd63b8ac2caafc049a95c4c83269007'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Si quiere tener el peor semestre de su vida adelante, matricule con él, luego no diga que no se le advirtió'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b99cc8453a14c3623d7e8aa5def8a9b1202ecedc84da6b11107c20220c703e23'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'El peor profe que he tenido en todo lo que llevo en el TEC. No dió ni una sola clase, el curso es autodidacta y en los exámenes puede meter materia que no está en el contenido del curso. Muchos estudiantes con ponderados altos y que nunca han tenido problemas reprobaron o fueron a repo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '226769289dad35443f009190f9a3ffe2b6789909fa75cd00a3685f98b43c2c72'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Un ASCO de profesor, en serio, ¿cómo lo contrataron de profe? Muchachos, si no les queda de otra que matricular con esta cosa, prepárense para ser completamente autodidactas y vean, obligatoriamente, los videos de Pablo Alvarado y Miguel Barboza, ellos sí son profes de verdad.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '31e1072d5cd13d7e6033502b2d8ff474c9619700dd6d0f75362d8213d789be9a'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'La peor basura de profesor. NO DA CLASES. Si son autodidactas adelante, pero sino no esperen nada de él. Vago, exámenes difíciles con materia que no se vió, solo manda videos super básicos que son leer el folleto del curso. Cero ejemplos, no le importa que se aprenda o no.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '8765e84b2076275021d45cafc903a4241a4d83d0dfeaf7d44d655da6ee41c025'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Horrible profe, explica pésimo, no da clases, básicamente hay que ser autodidacta, mete cosas en el examen que no se vieron en clase.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '44b21284841776def9898f199ca56bea978142c2b87a287766f66a3d0f55f560'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'En la modalidad virtual, solo hace videos super cortos y superficiales mientras lee del libro, Muchas veces comete los mismos errores que hay en el libro, y no los corrige o no explica como lo hizo. Puede meter cosas en los exmaenes que no venian en la materia'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '69b9888bf87c239f2d0f443fae7e5c81775155113ae9692d343cd61ea89073fc'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'En las clases presenciales solo iba a leer el libro y hacer los ejemplos que ya vienen resueltos, en modalidad virtual no dio una sola clase, solo dejaba guías. No se aprende nada.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'bc9499945c54bfa1d040d066bc0fc38b15bf5c85ebdd87e7eeb333d10bd6aaeb'::TEXT, ARRAY[3068]::BIGINT[]),
    (1180::BIGINT, 'No se si algún día él lea esto pero me decepcionó tanto que el TEC tenga profesores así, no dio ni una sola clase en modalidad virtual, a pesar de que era obligatorio, envió prácticas elaboradas por otro profe y guías teóricas, mientras aplicaba exámenes prácticos que calificaba muy duro. EL PEOR!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'e63a40f24e804f52cbb91e39796e3b310dc6f7394a349daf61b3d58f69dfde03'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'En la modalidad presencial el profe omite muchas cosas importantes y hace la clase más teórica. Por lo que, fuera de clases toca hacer muchos ejercicios. En la modalidad virtual solo dejaba guías de estudio y él solo se conectaba para aclarar dudas, por lo que se debe ser muy autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '8fbcb29dcaed0bf6e47f16d3269b5ecc48baa0d20dbbf36be02c00bc42b56d0e'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Felicidades, el curso lo pasa cualquiera. Las mala noticias son que el mae te va a dar A LO MUCHO 1 hora de las 4 de clase, no hay retroalimentacion y no se aprende nada... Ooops. Ah y ojala no le caiga mal porque sino se vuelve el mae mas metiCULOso del mundo para buscarle errores a su proy.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '06c1540b674e0d1640ef78598eeaa68b483bfe93cb6c61feabb3dde23c82aced'::TEXT, ARRAY[3078]::BIGINT[]),
    (1180::BIGINT, 'Jaime realmente no prepara sus clases, es poco profesional, él llega a ver qué sale. El curso es un regalo, siempre y cuando a él le guste su proyecto, si no le gusta pues le va a bajar puntos por cosas tontas. Además, que siempre siempre proyectos que tienen costos económicos altos.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'a2dbd3122befe8b492c5e2751fb9462c84f348149057ea302c91833f3224f55f'::TEXT, ARRAY[3070]::BIGINT[]),
    (1180::BIGINT, 'Buen profesor para este curso. Deja demasiado trabajo al principio, pero despues de S8, el curso es entretenido. No dio notas sino hasta el puro final del semestre. Usualmente pone 100 todo si se es puntual.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3fb4040099af99589d90730da50418bace2b5b3c806750413fb4b5aa494c82d8'::TEXT, ARRAY[3071]::BIGINT[]),
    (1180::BIGINT, 'El profesor puede sentirse algo estricto, pero realmente no revisa tan duro. Lo que son las bitácoras, pues creo que ni las lee, así que todo bien, y con los proyectos, pues si tiene bastantes "críticas constructivas", pero evalua decente, simplemente no dormirse con esos proyectos y se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c18008e7b63e30cd41d1a6a257245dbf8cd60e33972dd8589508a27298119e2a'::TEXT, ARRAY[3056]::BIGINT[]),
    (1180::BIGINT, 'No manejaba mucho la materia y lo que se veía en clases era muy teórico y no aplicable. Los exámenes no se parecían a la materia vista y eran bastante largos y difíciles. Tras de eso, era casi imposible reclamarle y se mostraba muy intransigente.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '61cf3c2f7e40d38fc3c7511a347d6e83f78ea65676a8f72a6678a789ead50369'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'venia mal preparado para las clases, no sabe responder a las preguntas y evaluo los examenes a un nivel muy diferente del visto en clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b18163df052db9950ab924702e28af42308cf927bb355f65beca210ae83661da'::TEXT, ARRAY[3057]::BIGINT[]),
    (1180::BIGINT, 'Un profesor que hace relucir la mediocridad de muchos estudiantes. Es un chiste.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-03-07T00:00:00+00:00'::TIMESTAMPTZ, '95f30307fc479e6871d89513f3d292ec419c8ffa0de203758e89f8fcbd147ebb'::TEXT, ARRAY[1410]::BIGINT[]),
    (1180::BIGINT, 'Es un profesor que apenas prepara sus lecciones, por lo que no se aprede mucho en clases.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-15T00:00:00+00:00'::TIMESTAMPTZ, '6c4e557073fa670e791e5eef592a1e161801b9b741ee7ad60b8c963ec72b87f8'::TEXT, ARRAY[3070]::BIGINT[]),
    (1180::BIGINT, 'Explica bien y es muy relajado, el curso se pasa solo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-12T00:00:00+00:00'::TIMESTAMPTZ, '2490ee877cf7149f210f52199b6f4004a978320245dee726d827c45b799bfe77'::TEXT, ARRAY[3070]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
